<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { worldApi } from '../api/world'
import type { Branch, TimelineEvent } from '../types'
const route = useRoute(); const worldId = Number(route.params.worldId); const branches = ref<Branch[]>([]); const timeline = ref<TimelineEvent[]>([]); const name = ref('雾中的另一种可能'); const selected = ref<TimelineEvent | null>(null); const message = ref(''); const loading = ref(false)
onMounted(async () => { branches.value = (await worldApi.branches(worldId)).data; if (branches.value[0]) timeline.value = (await worldApi.timeline(worldId, branches.value[0].id)).data })
async function fork() { if (!selected.value || !branches.value[0]) return; loading.value = true; try { await worldApi.fork(worldId, branches.value[0].id, selected.value.id, name.value); message.value = '新分支已从这个历史节点创建。'; branches.value = (await worldApi.branches(worldId)).data } catch (err: any) { message.value = err.response?.data?.message || '这个节点暂时无法分支。' } finally { loading.value = false } }
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">BRANCH CONTROL / POSSIBILITY SPACE</p><h1>分支管理</h1><p class="lede">从某个历史节点复制世界，让另一种可能继续生长。</p></div></div><div class="branch-layout"><div class="branch-list"><article v-for="branch in branches" :key="branch.id" :class="['branch-card', { active: branch.id === branches[0]?.id }]" @click="branch.id === branches[0]?.id && (timeline = timeline)"><span class="card-index">BRANCH #{{ branch.id }}</span><h3>{{ branch.name }}</h3><p>{{ branch.parentBranchId ? `来自分支 #${branch.parentBranchId}` : '世界起点' }}</p><em>{{ branch.status }}</em></article></div><div class="panel fork-panel"><p class="eyebrow">FORK FROM TIMELINE</p><h2>选择历史节点</h2><div class="fork-nodes"><button v-for="event in timeline" :key="event.id" :class="['fork-node', { selected: selected?.id === event.id }]" @click="selected = event"><span>#{{ event.id }} · {{ event.occurredOn }}</span><strong>{{ event.summary }}</strong></button><div v-if="!timeline.length" class="empty-state">推进世界后，这里会出现可分支的节点。</div></div><input v-model="name" placeholder="新分支名称" /><button class="primary-button full-width" :disabled="!selected || loading" @click="fork">{{ loading ? '复制中…' : '从此处创建分支 →' }}</button><p v-if="message" class="success-message">{{ message }}</p></div></div></section></template>
